package service

import (
	"context"
	"errors"
	"time"

	"gorm.io/gorm"

	"github.com/maburvm/panel/internal/shared/secret"
)

// A new VM's root password is generated by the panel, and somebody has to be
// told it. Email is the wrong place: a mailbox keeps it for ever, forwards it,
// and is read by whoever gets into the mailbox. So the password is kept here
// instead, encrypted, for a short time. The "your server is ready" email only
// points at the VM's page, where the owner reads it after signing in (with
// their second factor, if they use one), and every read is recorded.

// InitialPasswordTTL is how long a generated root password can be read back.
const InitialPasswordTTL = 72 * time.Hour

// ErrNoInitialPassword means there is nothing to show: none was generated, it
// has expired, or it has been erased.
var ErrNoInitialPassword = errors.New("no stored password for this VM")

// StoreInitialPassword keeps a generated root password for its owner to read,
// replacing any earlier one for the same VM.
func StoreInitialPassword(ctx context.Context, db *gorm.DB, vmID, password string) error {
	pair, err := secret.Resolve()
	if err != nil {
		return err
	}
	enc, err := encryptWithKey([]byte(pair.AES), password)
	if err != nil {
		return err
	}
	return db.WithContext(ctx).Exec(
		`INSERT INTO vm_initial_secrets (vm_id, ciphertext, created_at, expires_at) VALUES (?, ?, now(), ?)
		 ON CONFLICT (vm_id) DO UPDATE SET ciphertext = EXCLUDED.ciphertext, created_at = now(), expires_at = EXCLUDED.expires_at`,
		vmID, enc, time.Now().Add(InitialPasswordTTL),
	).Error
}

// InitialPasswordExpiry reports until when a VM's generated password can still
// be read, or nil when there is none.
func InitialPasswordExpiry(ctx context.Context, db *gorm.DB, vmID string) (*time.Time, error) {
	var rows []struct{ ExpiresAt time.Time }
	if err := db.WithContext(ctx).Raw(
		`SELECT expires_at FROM vm_initial_secrets WHERE vm_id = ? AND expires_at > now()`, vmID,
	).Scan(&rows).Error; err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}
	return &rows[0].ExpiresAt, nil
}

// RevealInitialPassword returns the stored password and when it expires.
func RevealInitialPassword(ctx context.Context, db *gorm.DB, vmID string) (string, time.Time, error) {
	var rows []struct {
		Ciphertext string
		ExpiresAt  time.Time
	}
	if err := db.WithContext(ctx).Raw(
		`SELECT ciphertext, expires_at FROM vm_initial_secrets WHERE vm_id = ? AND expires_at > now()`, vmID,
	).Scan(&rows).Error; err != nil {
		return "", time.Time{}, err
	}
	if len(rows) == 0 {
		return "", time.Time{}, ErrNoInitialPassword
	}
	pair, err := secret.Resolve()
	if err != nil {
		return "", time.Time{}, err
	}
	plain, err := decryptWithKey([]byte(pair.AES), rows[0].Ciphertext)
	for _, old := range pair.AESPrevious {
		if err == nil {
			break
		}
		plain, err = decryptWithKey([]byte(old), rows[0].Ciphertext)
	}
	if err != nil {
		return "", time.Time{}, err
	}
	return plain, rows[0].ExpiresAt, nil
}

// ForgetInitialPassword erases a VM's stored password now, for an owner who
// has saved it and does not want it kept.
func ForgetInitialPassword(ctx context.Context, db *gorm.DB, vmID string) error {
	return db.WithContext(ctx).Exec(`DELETE FROM vm_initial_secrets WHERE vm_id = ?`, vmID).Error
}

// PurgeInitialPasswords erases every stored password that has expired.
func PurgeInitialPasswords(ctx context.Context, db *gorm.DB) (int64, error) {
	res := db.WithContext(ctx).Exec(`DELETE FROM vm_initial_secrets WHERE expires_at <= now()`)
	return res.RowsAffected, res.Error
}
